import React from 'react';

export default function BookingCodeCard({ booking }) {
  if (!booking) return null;
  const copy = async () => {
    try { await navigator.clipboard.writeText(booking.code || ''); alert('Copied'); }
    catch { alert('Copy failed'); }
  };

  return (
    <div className="card" style={{ padding: 12, textAlign: 'center' }}>
      <h3>Your Booking Code</h3>
      <div style={{ fontSize: 28, letterSpacing: 2, margin: '12px 0', fontWeight: 700 }}>{booking.code || booking.bookingCode?.code}</div>
      <div>Expires: {booking.bookingCode?.expiryDate ? new Date(booking.bookingCode.expiryDate).toLocaleString() : 'N/A'}</div>
      <div style={{ marginTop: 12 }}>
        <button className="btn" onClick={copy}>Copy</button>
      </div>
    </div>
  );
}
